pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address _owner, address caller) public {
        vm.assume(caller != address(0) && _owner != address(0));
        vm.assume(caller != _owner);
        vm.prank(c.owner());
        c.setOwner(caller);
        vm.prank(caller);
        c.setOwner(_owner);
        assertTrue(c.owner() == _owner);
    }
}
